#define DEBUG_LEVEL 2          // 0 — без отладки, 1 — число шагов, 2 — каждый шаг

int main(void) {
    int value, steps = 0;
    long long sum = 0;
    while (scanf("%d", &value) == 1) {
        steps++;
        sum += value;
#if DEBUG_LEVL >= 2
        printf("шаг %d: %+d, сумма %lld\n", steps, value, sum);
#endif
    }
#if DEBUG_LEVEL >= 1
    printf("шагов: %d\n", steps);
#endif
    printf("сумма: %lld\n", sum);
    return 0;
}

